def comps_of(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                q=[(i,j)]; seen[i][j]=True; cells=[]; col=g[i][j]
                while q:
                    x,y=q.pop(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
