                            seen[a][b]=True; q.append((a,b))
                out.append((col,cells))
    return out

def canon(cells):
    # try all 8 dihedral variants, pick lexicographically smallest tuple of offsets
    best=None
    cur=sorted(cells)
    for flip in (False,True):
        pts=sorted((p[0], p[1]* -1 if flip else p[1]) for p in cur)
        pts=[(p[0],-p[1]) if flip and True else p for p in pts]
        h=max(p[0] for p in pts)-min(p[0] for p in pts)+1
        w=max(p[1] for p in pts)-min(p[1] for p in pts)+1
        m=[[0]*(w) for _ in range(h)]
        for x,y in pts: m[x][y]=1
        t=tuple(tuple(row) for row in m)
        if best is None or t<best: best=t
        # rotate 90: transpose + mirror cols
        next_m=[[m[j][i] for j in range(h)] for i in range(w)]
        m=next_m; h,w=w,h
    return best

