    for flip in (False,True):
        pts=[(p[0],-p[1] if flip else p[1]) for p in m]
        h=max(p[0] for p in pts)-min(p[0] for p in pts)+1
        w=max(p[1] for p in pts)-min(p[1] for p in pts)+1
        grid=tuple(tuple('X' if any((x,y)==p for p in pts) else '.' for y in range(w)) for x in range(h))
