    mn=(min(p[0] for p in cells),min(p[1] for p in cells))
    return tuple(sorted((p[0]-mn[0],p[1]-mn[1]) for p in cells))
def solve(g):
    c=comps_of(g)
    out=[row[:] for row in g]
    for col,cells in c:
        if col==1:
            pat=strict_canon(cells)
            tgt=[co for co,cl in c if co!=1 and strict_canon(cl)==pat]
            if len(tgt)!=1: continue
            for x,y in cells: out[x][y]=tgt[0]
    return out
for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    print(k, solve(G[k+' input'])==G[k+' output'])
print(json.dumps(solve(G['Test input'])))

